INSERT INTO mmd_blog_post (title, url_key, excerpt, content, author, status, published_at, related_skus, source_sku, hero_image_url, meta_title, meta_description, meta_keywords, created_at, updated_at) SELECT 'From Market Research to a RAG Bakery Website: Agentic AI with Codex in Class', 'agentic-ai-codex-bakery-academy-class-september-2026', 'Dr Alfred Ang led six participants through an Agentic AI Applications with Codex class on 26 September 2026: ChatGPT market research, a fictitious bakery academy website and RAG assistant with Codex, and operations and marketing with ChatGPT Work.', '<p>On 26 September 2026, <strong>Dr Alfred Ang</strong> conducted Agentic AI Applications with Codex for a group of six participants. The class used one connected business scenario: a <strong>fictitious Cook &amp; Bake Academy</strong>. The aim was to see how AI tools can support a business journey, from checking an idea to building a customer-facing site and planning its day-to-day work.</p> <p>The exercise linked three kinds of work. Participants used <strong>ChatGPT for market research</strong>, <strong>Codex to build a bakery academy website and retrieval-augmented generation (RAG) course assistant</strong>, and <strong>ChatGPT Work for operations and marketing</strong>. The public <a href="https://github.com/tertiarycourses/C695-Agentic-AI-Applications-with-Codex">Cook &amp; Bake Academy learning repository</a> documents the scenario, materials and lab sequence. It is a C695 non-WSQ learning package; the registration link for the WSQ course is below.</p> <h2>Start with a question worth testing</h2> <p>Before asking an agent to make a website, the group considered the market for a cooking and baking academy. ChatGPT helped frame research questions, compare possible offerings and organise findings into a usable brief. The important habit was to separate a researched observation from an assumption. A polished AI answer does not, by itself, establish demand or a viable price.</p> <p>That brief gave the build a purpose: visitors should be able to explore courses, understand what each workshop offers and find a clear route to register their interest.</p> <h2>Use Codex to turn the brief into a website</h2> <p>The Cook &amp; Bake Academy scenario contains a sample catalogue of 20 hands-on courses. In the repository, the website exercises move from planning and project rules to course pages, sign-up forms and browser checks. Codex works across the project files, while the learner remains responsible for the requirements and for reviewing the result.</p> <p>The scenario also adds a <strong>RAG course assistant</strong>. Course information is organised in a SQLite knowledge base so a visitor can ask about workshops and receive answers grounded in the academy material. The public labs cover building the assistant, testing its answers and trying questions designed to expose weak or unsupported responses. That evaluation step matters: a helpful-looking chatbot still needs to be checked against its source material.</p> <h2>Run the academy with ChatGPT Work</h2> <p>A website is only one part of the exercise. The repository continues into pricing and break-even analysis, a term calendar, enrolment and reminder workflows, customer service, and marketing content. ChatGPT Work provides a way to organise those operational tasks around the same academy scenario. The class discussion connected the tools to practical questions: what evidence supports a price, what information belongs in a learner reminder, and what a human should approve before a campaign goes out.</p> <p>The marketing labs extend the scenario into reusable skills, a flyer, content planning and an open-house campaign. These are examples from the published learning package, not a claim that every lab or campaign was completed by this six-person class today.</p> <h2>One scenario, several AI roles</h2> <ul><li><strong>ChatGPT</strong> helps explore and structure the market question.</li><li><strong>Codex</strong> turns requirements into site features and a grounded course assistant, then supports review and testing.</li><li><strong>ChatGPT Work</strong> helps organise the operational and marketing work that surrounds the site.</li></ul> <p>The lesson is the connection between the stages. Research shapes the brief; the brief shapes the build; the build creates information and workflows that operations and marketing must maintain. Each stage calls for a person to check the evidence, decisions and output.</p> <h2>Learn to build agentic applications with Codex</h2> <p>If you want to practise this kind of end-to-end workflow, explore <a href="https://www.tertiarycourses.com.sg/wsq-agentic-ai-applications-with-codex.html"><strong>WSQ Agentic AI Applications with Codex</strong></a> (TGS-2023041081). The two-day course covers application planning, Codex Skills and MCP tools, RAG and multi-agent patterns, and testing and evaluation. The course page has the current schedule, entry requirements and funding details.</p> <p><a href="https://www.tertiarycourses.com.sg/wsq-agentic-ai-applications-with-codex.html"><strong>View the WSQ course and register your interest.</strong></a> You can also browse the <a href="https://github.com/tertiarycourses/C695-Agentic-AI-Applications-with-Codex">public Cook &amp; Bake Academy repository</a> to see how the learning scenario is organised.</p> <h2>Frequently asked questions</h2> <div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Is Cook &amp; Bake Academy a real business?</summary><div class="mmd-faq-a"><p>No. It is a fictitious academy used as a safe, connected scenario for the exercises.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What does the RAG assistant use for answers?</summary><div class="mmd-faq-a"><p>The repository exercise grounds answers in an academy course knowledge base built with SQLite. Learners test whether responses match the source material.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the linked GitHub package the WSQ registration page?</summary><div class="mmd-faq-a"><p>No. The GitHub package documents the C695 learning scenario. For WSQ course details and registration, use the <a href="https://www.tertiarycourses.com.sg/wsq-agentic-ai-applications-with-codex.html">WSQ Agentic AI Applications with Codex page</a>.</p></div></details></div>', 'Tertiary Infotech Academy', 2, '2026-09-26', 'TGS-2023041081', 'TGS-2023041081', 'https://www.tertiarycourses.com.sg/skin/frontend/ultimo/default/images/blog/codex-bakery-academy-class-20260926.png', 'Agentic AI with Codex Class: Bakery Academy RAG Website | Tertiary Infotech', 'Six learners explored market research, a Codex-built bakery academy site and RAG assistant, and ChatGPT Work operations with Dr Alfred Ang.', 'Agentic AI Applications with Codex, Codex course Singapore, ChatGPT Work, RAG chatbot, bakery academy, WSQ agentic AI', '2026-09-26 09:00:00', '2026-09-26 09:00:00' FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM (SELECT post_id FROM mmd_blog_post WHERE url_key = 'agentic-ai-codex-bakery-academy-class-september-2026') existing);
